export interface SpriteResult {
  imageUrl: string;
  prompt: string;
  timestamp: number;
}

export enum GenerationStyle {
  CLASSIC_16BIT = '16-bit Classic',
  MODERN_HD = 'Modern HD Pixel',
  GAMEBOY = 'GameBoy Retro',
  FANTASY = 'Epic Fantasy',
  CYBERPUNK = 'Cyberpunk'
}

export interface GenerationSettings {
  style: GenerationStyle;
  frameCount: number;
  includeWalkCycle: boolean;
  backgroundColor: 'transparent' | 'white' | 'black' | 'green';
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { GenerationSettings, GenerationStyle } from "../types";

export const generateSpriteSheet = async (
  base64Image: string,
  settings: GenerationSettings
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const styleDescription = {
    [GenerationStyle.CLASSIC_16BIT]: "SNES-style 16-bit pixel art with limited vibrant color palette",
    [GenerationStyle.MODERN_HD]: "High-definition pixel art with smooth shading and detailed textures",
    [GenerationStyle.GAMEBOY]: "4-color monochrome green palette, classic 8-bit handheld aesthetic",
    [GenerationStyle.FANTASY]: "Detailed fantasy pixel art with magical effects and ornate equipment",
    [GenerationStyle.CYBERPUNK]: "Neon-infused pixel art with high contrast and technological details"
  }[settings.style];

  const prompt = `
    ACT AS A PROFESSIONAL GAME ASSET ARTIST. 
    Task: Convert the attached character image into a professional 2D pixel art sprite sheet.

    Character Style: 
    - 2-head tall (Chibi/SD) proportions.
    - Style: ${styleDescription}.

    Sprite Sheet Layout:
    - Create a clean grid-based sprite sheet.
    - Include multiple frames: 
      1. Idle animation (front, side, back)
      2. ${settings.includeWalkCycle ? 'Walking animation cycle (front, side, back)' : 'Basic poses'}
    - Total Frames: Approximately ${settings.frameCount} frames.
    - Perspective: Top-down 3/4 RPG perspective (standard for Pokemon/Stardew Valley style games).

    Technical Details:
    - Background: ${settings.backgroundColor === 'transparent' ? 'Solid neutral grey (to be removed later)' : `Solid ${settings.backgroundColor}`}.
    - Clear outlines, readable features, and consistent lighting.
    - Do not include any text, UI, or watermarks in the image.
    - The output MUST be a single image file containing the sprite sheet.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png',
              data: base64Image.split(',')[1],
            },
          },
          { text: prompt },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    let imageUrl = '';
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }
    }

    if (!imageUrl) {
      throw new Error("No image was generated by the model.");
    }

    return imageUrl;
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'pixel';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-4 py-2 rounded-lg font-medium transition-all duration-200 disabled:opacity-50 flex items-center justify-center gap-2";

  const variants = {
    primary: "bg-indigo-600 hover:bg-indigo-700 text-white",
    secondary: "bg-slate-700 hover:bg-slate-600 text-white",
    outline: "border-2 border-slate-700 hover:border-slate-600 text-slate-300",
