          <div className="bg-slate-900 p-4 rounded-xl border border-slate-700/50 group relative overflow-hidden">
            <img 
              src={imageUrl} 
              alt="Generated Sprite Sheet" 
              className="w-full h-auto image-pixelated rounded-lg"
              style={{ imageRendering: 'pixelated' }}
            />
            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
               <a 
                href={imageUrl} 
                download="sprite-sheet.png"
                className="bg-white text-black px-4 py-2 rounded-lg font-bold hover:bg-slate-200 transition-colors"
               >
                 Download Assets
               </a>
            </div>
          </div>
        </div>

        {/* Animation Preview */}
        <div className="w-full md:w-64 flex flex-col items-center">
          <h3 className="text-sm font-semibold text-slate-400 mb-4 uppercase tracking-wider">Animation Test</h3>
          <div className="w-48 h-48 bg-slate-900 rounded-xl border-4 border-slate-700 flex items-center justify-center overflow-hidden bg-[url('https://www.transparenttextures.com/patterns/checkerboard.png')] bg-center">
            {/* Simple CSS Sprite Animation simulation */}
            <div className="relative w-32 h-32 overflow-hidden flex items-center justify-center">
                <img 
                    src={imageUrl} 
                    alt="Animation Preview"
                    className="absolute max-w-none h-full"
                    style={{ 
                        imageRendering: 'pixelated',
                        left: `-${frame * 100}%`,
                        width: `${totalFrames * 100}%`,
                        objectFit: 'contain'
                    }}
                />
            </div>
          </div>
          <p className="mt-4 text-xs text-slate-500 text-center italic">
            *Auto-detected cycle simulation
